{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 질병을 알고도 적절한 조치를 하지 않고 방치한 행위가 동물학대 정의에 해당하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제2조제10호는 동물학대를 \"동물을 대상으로 정당한 사유 없이 불필요하거나 피할 수 있는 고통과 스트레스를 주는 행위 및 굶주림, 질병 등에 대하여 적절한 조치를 게을리하거나 방치하는 행위\"로 정의한다. 따라서 질병을 알고도 적절한 조치를 하지 않고 방치한 행위는 위 정의상 동물학대에 해당할 수 있다.",
          "b_ids": "동물보호:제2조제10호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
